                        + h[21] + (h[22] <<< 1) + h[22] + (h[23] <<< 1) + -h[24] + -h[25] + -h[27] + -((h[28] <<< 1) +
                        h[28]) + -h[29] + (h[30] <<< 1) + h[30] + -h[31];
    assign fc2_raw[6] = h[0] + -(h[1] <<< 1) + -((h[2] <<< 1) + h[2]) + (h[3] <<< 1) + -((h[4] <<< 1) + h[4]) + -((h[5] <<<
                        1) + h[5]) + -((h[7] <<< 1) + h[7]) + -h[8] + (h[9] <<< 1) + h[9] + -(h[10] <<< 1) + h[11] + (h[12]
                        <<< 1) + h[12] + (h[13] <<< 1) + h[13] + -((h[14] <<< 1) + h[14]) + -h[15] + -((h[16] <<< 1) +
                        h[16]) + -((h[17] <<< 1) + h[17]) + -((h[18] <<< 1) + h[18]) + -h[20] + -h[21] + -((h[24] <<< 1) +
                        h[24]) + -h[26] + (h[27] <<< 1) + -((h[28] <<< 1) + h[28]) + -((h[29] <<< 1) + h[29]) + (h[30] <<<
                        1) + -h[31];
    assign fc2_raw[7] = -h[0] + (h[1] <<< 1) + h[1] + (h[2] <<< 1) + -(h[3] <<< 1) + -h[4] + -(h[5] <<< 1) + -h[7] + -((h[8]
                        <<< 1) + h[8]) + h[10] + -((h[12] <<< 1) + h[12]) + (h[13] <<< 1) + h[13] + (h[14] <<< 1) + h[14] +
                        -h[16] + (h[17] <<< 1) + (h[18] <<< 1) + h[19] + -((h[20] <<< 1) + h[20]) + -h[22] + -((h[23] <<< 1)
