    // logit_out is a flattened packed bus; each 16-bit logit i lives at
    // bit offset i*16 (indexed part-select, Verilog-2001 legal).
    genvar gn2;
    generate
        for (gn2 = 0; gn2 < 10; gn2 = gn2 + 1) begin : norm2_shift
            assign logit_out[gn2*16 +: 16] = fc2_raw[gn2];
        end
    endgenerate

endmodule

// ============================================================
// Argmax: finds the digit with highest logit
// ============================================================
module argmax10 (
    input  wire signed [159:0] logit_in,   // 10 × 16-bit logits, flattened: logit_in[i*16 +: 16]
    output reg  [3:0]          digit_out   // 0-9
);
    integer i;
    reg signed [15:0] max_val;
    always @(*) begin
        max_val   = logit_in[0 +: 16];
        digit_out = 4'd0;
        for (i = 1; i < 10; i = i + 1) begin
            if ($signed(logit_in[i*16 +: 16]) > max_val) begin
                max_val   = logit_in[i*16 +: 16];
                digit_out = i[3:0];
            end
        end
    end
endmodule

// ============================================================
// Top wrapper: pixels in → digit out
// ============================================================
module bitnet_mini_top (
    input  wire [195:0] pixel_in,
    output wire [3:0]   digit_out
);
    wire signed [159:0] logits_flat;
    bitnet_mini  nn  (.pixel_in(pixel_in), .logit_out(logits_flat));
    argmax10     ax  (.logit_in(logits_flat), .digit_out(digit_out));
endmodule


// ============================================================
// Top wrapper: combinational to timed
// ============================================================
module digit_classifier (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         start,
    input  wire [195:0] image_in,
    output reg  [3:0]   digit_out,
    output reg          valid_out
);
    wire [3:0] nn_digit;

    // Instantiate the generated BitNetMini
    bitnet_mini_top nn (
        .pixel_in  (image_in),
        .digit_out (nn_digit)
    );

    reg valid_pipe;

    always @(posedge clk) begin
        if (!rst_n) begin
            digit_out  <= 4'd0;
            valid_pipe <= 1'b0;
            valid_out  <= 1'b0;
        end else begin
            valid_pipe <= 1'b0;  // default
            valid_out  <= valid_pipe;

            if (start) begin
                $display("image_array=%b", image_in);
                $display("image_array_int=%d", image_in);
                $display("nn_digit=%d", nn_digit);
                digit_out  <= nn_digit;  // cycle N:   data latched
                valid_pipe <= 1'b1;      // cycle N+1: valid_out goes high
            end                          // cycle N+1: top reads digit_out — it's stable
        end
    end


endmodule